import { useRouter } from 'vue-router';

setup() {
  const router = useRouter();

  const openModal = () => {
    router.push({ name: 'modal', state: { modalOpen: true } });
  };

  const closeModal = () => {
    router.back();
  };

  return { openModal, closeModal };
}
```

### Best Practices

- **Clean Up:** Always use `replaceState` or `back()` to remove the modal state from history when closing.
- **Accessibility:** Use semantic HTML and ARIA attributes (`role="dialog"`, `aria-modal="true"`).
- **Keyboard Navigation:** Ensure `Escape` key closes the modal for better UX.
- **Focus Management:** Move focus to the modal on open and restore it on close.
- **Testing:** Test across different browsers and device types.

By using the History API and listening to `popstate` events, you can ensure that pressing the back button gracefully closes your modal without navigating away from the page.
